    WHERE  a.polygon_raw_json is not null
        and is_json_scalar (json_extract(micromobility_vehicle_types, '$.[0]')) = true
        AND {% condition city_area_type %} a.type {% endcondition %}
        AND {% condition city_filter %} c.name {% endcondition %}
    --    AND a.is_deleted = 'false'
    )

      SELECT
      date(date_add('hour', timezone_hour(at_timezone(ro.created, timezone)), ro.created)) period
      , ro.city_id
      , v.model as model
      , ca.name as city_area_name
      , ca.is_deleted
      , ca.id as city_area_id
      , ro.currency as currency
      , count(distinct ro.vehicle_id) vehicles_with_min_1_trip
      , 1.00*avg(track_distance_m)/1000 as average_order_distance
      , sum(price) sum_prices
      , count(distinct ro.id) ride_count
      , count(distinct date(date_add('hour', timezone_hour(at_timezone(ro.created, timezone)), ro.created))) period_count
      FROM ng_rental.rental_order_order ro
      JOIN ng_rental.rental_fleet_vehicle v ON v.id=ro.vehicle_id
      JOIN admin_system_city c on ro.city_id = c.id
      LEFT JOIN city_areas ca
      ON c.id=ca.city_id
      AND ST_Contains(ST_GeometryFromText('POLYGON((' || ca.shape_1 || '))'), ST_Point(ro.dropoff_lat,ro.dropoff_lng))
      WHERE ro.state= 'finished'
      AND {% condition city_filter %} c.name {% endcondition %}
      AND ro.created_date>={% date_start period_filter %} and ro.created_date<{% date_end period_filter %}
      GROUP BY 1,2,3,4,5,6,7;;

  }

  dimension_group: period {
    type: time
    sql: ${TABLE}.period ;;
    convert_tz: no
  }

  dimension: city_id {
    type: number
    sql: ${TABLE}.city_id ;;
  }

  dimension: vehicle_type {
    type: string
    sql: CASE
          WHEN ${TABLE}.model = 'es2' THEN 'Segway ES2'
          WHEN ${TABLE}.model = 'es4' THEN 'Segway ES4'
          WHEN ${TABLE}.model = 'es_max' THEN 'Segway ES Max'
          WHEN ${TABLE}.model = 'es_max_swappable' THEN 'Segway ES Max Swappable'
          WHEN ${TABLE}.model = 'stigo' THEN 'Valk'
          WHEN ${TABLE}.model = 'zimo' THEN 'Zimo S1'
          WHEN ${TABLE}.model = 'hj_ebike' THEN 'HJ Ebike'
          WHEN ${TABLE}.model = 'cobra' THEN 'Cobra'
          WHEN ${TABLE}.model = 'es_max_swappable_plus' THEN 'Segway ES Max Swappable Plus'
          WHEN ${TABLE}.model = 'es_max_swappable_plus_sl' THEN 'Segway ES Max Swappable Plus SL'
          WHEN ${TABLE}.model = 'okai_scooter_es400' THEN 'OKAI ES400'
          WHEN ${TABLE}.model = 'okai_scooter_es600' THEN 'OKAI ES600'
