{noformat}private func handlePaymentMethodSelection(paymentMethod: PaymentMethodV2?) {
    guard let paymentMethod = paymentMethod else { return }
    let categoryBeforeUpdate = categoryProvider.selectedCategory?.category
    rideOptionsPollingMonitor.enforceRestart()
        .done { [weak self] in
            let categoryAfterUpdate = self?.categoryProvider.selectedCategory?.category
            if categoryAfterUpdate?.identifier == categoryBeforeUpdate?.identifier {
                self?.initiateCreateOrderSequence()
            } else if let _categoryBeforeUpdate = categoryBeforeUpdate {
                // category list could change depending on the payment method
                // show snackar if previously selected category is not selected anymore
                self?.showSnackbar(settings: SnackbarSettings(
                    titleText: L10n.ConfirmCategory.NotAvailableDuePaymentMethod.title(
                        _categoryBeforeUpdate.name,
                        paymentMethod.name
                    )
                ))
            }
        }
        .cauterize()
}{noformat}

